function scopeValue(t){const choice=$('scopeprobe').value,b=board(),bc=b&&catalog.find(c=>c.type===b.type);if(choice==='demo-sine')return{v:2.5+2*Math.sin(t/1000*Math.PI*2),i:NaN,demo:true};if(choice==='demo-square')return{v:(t/1000%1)<.5?5:0,i:NaN,demo:true};let v=nodes.find(n=>n.type==='source')?.value??bc?.value??0;if(b&&(choice.startsWith('pin:')||choice==='auto')){const pin=choice.startsWith('pin:')?choice.slice(4):Object.keys(pinModes).find(p=>pinModes[p]===1);if(pin){if(pinModes[pin]===1)v=(pinState[pin]||0)*bc.value;else{try{v=readPin(pin.startsWith('A')?pin:+pin.replace(/\D/g,''),true)/1023*bc.value}catch{v=NaN}}}}return{v,i:running?lastSim.current*1000:NaN,demo:false}}
$('scopefreeze').onclick=()=>{scopeFrozen=!scopeFrozen;$('scopefreeze').textContent=scopeFrozen?'המשך':'הקפאה';$('scopestate').textContent=scopeFrozen?'מוקפא':'דגימה חיה'};function clearScope(){scopeSamples=[];scopeLast=0}$('scopeprobe').onchange=clearScope;$('scopeclear').onclick=clearScope;$('scopeexport').onclick=()=>{if(!scopeSamples.length)return toast('אין עדיין דגימות לייצוא');const t0=scopeSamples[0].t;download('voltlab-scope.csv','time_ms,voltage_V,current_mA,source\n'+scopeSamples.map(s=>[(s.t-t0).toFixed(2),Number.isFinite(s.v)?s.v.toFixed(5):'',Number.isFinite(s.i)?s.i.toFixed(5):'',s.demo?'demo':'circuit'].join(',')).join('\n'),'text/csv')};
window.captureScopeChange=t=>{if(!running||scopeFrozen||$('scopeprobe').value.startsWith('demo-'))return;const next=scopeValue(t),previous=scopeSamples.at(-1);if(previous&&(Object.is(previous.v,next.v)&&Object.is(previous.i,next.i)))return;if(previous)scopeSamples.push({...previous,t:t-.01});scopeSamples.push({t,...next});if(scopeSamples.length>1800)scopeSamples.splice(0,scopeSamples.length-1800)};
window.scopeFrame=t=>{if(!scopeVisible||document.hidden||$('modal').open||t-scopeDrawLast<33)return;scopeDrawLast=t;const isDemo=$('scopeprobe').value.startsWith('demo-');if(!scopeFrozen&&(running||isDemo)&&t-scopeLast>=16){scopeLast=t;scopeSamples.push({t,...scopeValue(t)});if(scopeSamples.length>1800)scopeSamples.splice(0,scopeSamples.length-1800)}const c=scopeCanvas,r=c.getBoundingClientRect();if(r.width<10)return;const dpr=Math.min(devicePixelRatio,1.5);if(c.width!==Math.round(r.width*dpr)||c.height!==Math.round(r.height*dpr)){c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr)}const w=r.width,h=r.height,g=scopeCtx;g.setTransform(dpr,0,0,dpr,0,0);g.fillStyle='#0b1520';g.fillRect(0,0,w,h);g.strokeStyle='#25364a';g.lineWidth=1;for(let j=0;j<=10;j++){g.beginPath();g.moveTo(j*w/10,0);g.lineTo(j*w/10,h);g.stroke()}for(let j=0;j<=8;j++){g.beginPath();g.moveTo(0,j*h/8);g.lineTo(w,j*h/8);g.stroke()}const latest=scopeSamples.at(-1),end=latest?.t??t,windowMs=+$('scopetime').value*10000,start=end-windowMs,volts=+$('scopescale').value,visible=scopeSamples.filter(s=>s.t>=start);function trace(key,color,units){g.beginPath();let first=true;for(const s of visible){if(!Number.isFinite(s[key])){first=true;continue}const x=(s.t-start)/windowMs*w,y=h*.82-s[key]/units*(h/8);if(first){g.moveTo(x,y);first=false}else g.lineTo(x,y)}g.strokeStyle=color;g.lineWidth=1.8;g.stroke()}trace('v','#74edbd',volts);trace('i','#b19af6',5);$('scopev').textContent=latest&&Number.isFinite(latest.v)?latest.v.toFixed(2)+' V':'— V';$('scopei').textContent=latest&&Number.isFinite(latest.i)?latest.i.toFixed(2)+' mA':'— mA';$('scopestate').textContent=scopeFrozen?'מוקפא':isDemo?'מחולל הדגמה':running?'דגימה חיה · עד 30 Hz':'ממתין להרצה';$('scopedemo').textContent=isDemo?'DEMO · לא אות מהמעגל':'';};
const fpsBadge=document.createElement('span');fpsBadge.id='fpsbadge';fpsBadge.textContent='ציור לפי הצורך · עד 30 FPS';document.querySelector('.viewbar').append(fpsBadge);let frameTimes=[];window.sceneFrameRendered=t=>{frameTimes.push(t);frameTimes=frameTimes.filter(x=>t-x<1000);fpsBadge.textContent=running?frameTimes.length+' FPS · תצוגה': 'ציור לפי הצורך · עד 30 FPS'};
